            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
            color: #2c2c2c;
            background: #fff;
            line-height: 1.6;
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        img {
            display: block;
        }

        /* Header */
        .header {
            position: sticky;
            top: 0;
            z-index: 1000;
            background: #fff;
            border-bottom: 1px solid #eee;
        }

        .header-top {
            background: #2c2c2c;
            color: #fff;
            text-align: center;
            padding: 8px 0;
            font-size: 12px;
            letter-spacing: 1px;
        }

        .header-main {
            max-width: 1440px;
            margin: 0 auto;
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 16px 40px;
        }

        .logo {
            font-size: 28px;
            font-weight: 300;
            letter-spacing: 4px;
        }

        .logo span {
            color: #c9a96e;
        }

        .nav {
            display: flex;
            gap: 32px;
        }

        .nav a {
            font-size: 14px;
            letter-spacing: 1px;
            padding: 8px 0;
            border-bottom: 2px solid transparent;
            transition: all 0.3s;
        }

        .nav a:hover,
        .nav a.active {
            border-bottom-color: #c9a96e;
            color: #c9a96e;
        }

        .header-actions {
            display: flex;
            align-items: center;
            gap: 20px;
        }

        .cart-icon {
            position: relative;
            font-size: 20px;
            cursor: pointer;
        }

        .cart-badge {
            position: absolute;
            top: -8px;
            right: -10px;
            background: #c9a96e;
            color: #fff;
            font-size: 10px;
            width: 18px;
            height: 18px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        /* Hero */
        .hero {
            position: relative;
            height: 600px;
            overflow: hidden;
        }

        .hero img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .hero-overlay {
            position: absolute;
            inset: 0;
            background: linear-gradient(to right, rgba(0,0,0,0.5), transparent);
            display: flex;
            align-items: center;
            padding-left: 80px;
