            font-size: 32px;
            font-weight: 300;
            letter-spacing: 4px;
            margin-bottom: 16px;
        }

        .banner p {
            font-size: 15px;
            color: #666;
            margin-bottom: 32px;
        }

        /* Features */
        .features {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 32px;
            padding: 60px 40px;
            max-width: 1440px;
            margin: 0 auto;
        }

        .feature-item {
            text-align: center;
            padding: 24px;
        }

        .feature-icon {
            font-size: 32px;
            margin-bottom: 16px;
        }

        .feature-item h4 {
            font-size: 15px;
            margin-bottom: 8px;
            font-weight: 500;
        }

        .feature-item p {
            font-size: 13px;
            color: #888;
        }

        /* Footer */
        .footer {
            background: #2c2c2c;
            color: #fff;
            padding: 60px 40px 30px;
        }

        .footer-content {
            max-width: 1440px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr;
            gap: 40px;
            margin-bottom: 40px;
        }

        .footer-brand h3 {
            font-size: 24px;
            letter-spacing: 3px;
            margin-bottom: 16px;
        }

        .footer-brand p {
            font-size: 13px;
            color: #aaa;
            line-height: 1.8;
        }

        .footer-col h4 {
            font-size: 15px;
            margin-bottom: 16px;
            color: #c9a96e;
        }

        .footer-col a {
            display: block;
            font-size: 13px;
            color: #aaa;
            margin-bottom: 10px;
            transition: color 0.3s;
        }

        .footer-col a:hover {
            color: #fff;
        }

        .footer-bottom {
            border-top: 1px solid #444;
            padding-top: 24px;
            text-align: center;
            font-size: 12px;
            color: #888;
        }

        @media (max-width: 1024px) {
